import{_ as s,C as o,c as i,o as n,a3 as a,G as r}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Recruitment dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/dashboard/recruitment-dashboard.md","filePath":"master/human-resources/recruitment/dashboard/recruitment-dashboard.md","lastUpdated":1792041590000}'),l={name:"master/human-resources/recruitment/dashboard/recruitment-dashboard.md"};function c(p,t,d,h,g,u){const e=o("ImagePopup");return n(),i("div",null,[t[0]||(t[0]=a('<h1 id="recruitment-dashboard" tabindex="-1">Recruitment dashboard <a class="header-anchor" href="#recruitment-dashboard" aria-label="Permalink to &quot;Recruitment dashboard&quot;">​</a></h1><p>The dashboard gives you a quick count of your hiring. It shows active job positions, applications received and people hired. A chart splits applicants by status. A filter bar sits above the cards.</p><blockquote><p><strong>In simple words:</strong> The dashboard shows your hiring numbers at a glance.</p></blockquote><p>Open <code>Dashboard → Recruitment</code> in the main menu. The page title is <strong>Dashboard</strong>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>The numbers come from applicants. Add some first. See <a href="./../applicants/add-applicant.html">Add an applicant</a>.</p></div><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>The filter bar sits at the top. It has six fields. All start empty, except <strong>Status</strong> and <strong>Date Range</strong>.</p><ul><li><strong>Job Position:</strong> a list of your active positions.</li><li><strong>Departments:</strong> a list of departments.</li><li><strong>Companies:</strong> a list of companies.</li><li><strong>Stages:</strong> a list of recruitment stages.</li><li><strong>Status:</strong> choose <strong>All</strong>, <strong>Ongoing</strong>, <strong>Hired</strong>, <strong>Refused</strong> or <strong>Archived</strong>. The default is <strong>All</strong>. <strong>Archived</strong> means inactive applicants. Refused applicants are inactive too.</li><li><strong>Date Range:</strong> a period. It starts as the current calendar year.</li></ul><p>Aureus remembers your <strong>Status</strong> choice during your session. Set it back to <strong>All</strong> when you want the full picture.</p>',9)),r(e,{src:"/images1/recruitment/dash_filters.png",alt:"Recruitment dashboard filter bar with Job Position, Departments, Companies, Stages, Status and Date Range"}),t[1]||(t[1]=a('<h2 id="job-position-overview-cards" tabindex="-1">Job Position Overview cards <a class="header-anchor" href="#job-position-overview-cards" aria-label="Permalink to &quot;Job Position Overview cards&quot;">​</a></h2><p>Three cards sit under the title <strong>Job Position Overview</strong>. Each card also shows a percentage line with an arrow. It compares the number with the period before.</p><ul><li><strong>Active Job Applications:</strong> the number of active job positions created in the date range.</li><li><strong>Total Applications:</strong> the number of applicants created in the date range.</li><li><strong>Hired Candidates:</strong> the number of applicants who reached a hired stage and have a <strong>Hired Date</strong>.</li></ul>',3)),r(e,{src:"/images1/recruitment/dash_stat_cards.png",alt:"Three stat cards: Active Job Applications, Total Applications and Hired Candidates"}),t[2]||(t[2]=a('<h2 id="applicant-overview-chart" tabindex="-1">Applicant Overview chart <a class="header-anchor" href="#applicant-overview-chart" aria-label="Permalink to &quot;Applicant Overview chart&quot;">​</a></h2><p>The bar chart has one bar for each status: <strong>Ongoing</strong>, <strong>Hired</strong>, <strong>Refused</strong> and <strong>Archived</strong>. A taller bar means more applicants in that status. The legend reads <strong>Applicant Overview</strong>.</p>',2)),r(e,{src:"/images1/recruitment/dash_applicant_chart.png",alt:"Applicant Overview bar chart with bars for Ongoing, Hired, Refused and Archived"}),t[3]||(t[3]=a('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The dashboard is for reading. To act on an applicant, open the <a href="./../applicants/applicant-list.html">Applicant list</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../applicants/applicant-list.html">Applicant list</a></li><li><a href="./../applicants/process-applicant.html">Process an applicant</a></li><li><a href="./../job-positions/job-positions.html">Job positions</a></li><li><a href="./../">Recruitment overview</a></li></ul>',3))])}const _=s(l,[["render",c]]);export{b as __pageData,_ as default};
